package com.bank.trading.service;

import java.util.HashMap;
import java.util.Map;
import java.util.logging.Logger;

// Longest contiguous run using at most two instrument types (fruits into baskets).
public class TradingRunAnalyzer {
    private static final Logger log = Logger.getLogger(TradingRunAnalyzer.class.getName());

    public int longestTwoTypeRun(int[] instruments) {
        if (instruments == null || instruments.length == 0) return 0;
        Map<Integer, Integer> counts = new HashMap<>(); // type → count in window
        int left = 0;
        int best = 0;
        final int MAX_TYPES = 2; // two baskets

        for (int right = 0; right < instruments.length; right++) {
            counts.merge(instruments[right], 1, Integer::sum); // expand

            while (counts.size() > MAX_TYPES) {                // need a 3rd basket → shrink
                int leftType = instruments[left];
                int newCount = counts.get(leftType) - 1;
                if (newCount == 0) counts.remove(leftType);
                else counts.put(leftType, newCount);
                left++;
            }
            best = Math.max(best, right - left + 1);
        }
        final int result = best;
        log.info(() -> "Longest two-instrument run = " + result + " trades");
        return best;
    }
}
