package com.bank.trading;

import com.bank.trading.service.TradingRunAnalyzer;
import java.util.Arrays;
import java.util.logging.Logger;

public class TradingRunDemo {
    private static final Logger log = Logger.getLogger(TradingRunDemo.class.getName());

    public static void main(String[] args) {
        // Chronological instrument-type codes traded by a desk.
        int[] instruments = {1, 2, 1, 3, 4, 3, 5, 5, 5};
        log.info(() -> "Instruments: " + Arrays.toString(instruments));

        TradingRunAnalyzer analyzer = new TradingRunAnalyzer();
        int length = analyzer.longestTwoTypeRun(instruments);

        log.info(() -> "Longest focused run uses 2 instruments across " + length + " trades.");
    }
}
